 "content": "def transform(grid):
    # Fill the interiors of hollow rectangular frames. The fill color is
    # determined by the frame size: interiors of 2x2 are 2, otherwise 7.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Locate connected components of non-background cells (frames).
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            # Frames are connected as a border; derive component's bounding box.
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            # Fill enclosed cells only when their original color is background.
            fill = 2 if (r1-r0-1, c1-c0-1)==(2,2) else 7
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    if grid[y][x] == bg:
                        out[y][x]=fill
    return out

